js="const PRODUCTS="+json.dumps([dict(id=a,name=b,cat=c,price=d,desc=e,sizes=f) for a,b,c,d,e,f in P])+";"
open("products.js","w").write(js)
CSS="""*{box-sizing:border-box}body{margin:0;font-family:'Helvetica Neue',Arial,sans-serif;color:#1f2a24;background:#faf8f4}a{color:inherit;text-decoration:none}
.ann{background:#2f4a3a;color:#f3efe6;text-align:center;font-size:13px;padding:8px;letter-spacing:.04em}
header{display:flex;align-items:center;justify-content:space-between;padding:18px 40px;background:#faf8f4;border-bottom:1px solid #e5dfd3;position:sticky;top:0;z-index:5}
.logo{font-family:Georgia,serif;font-size:24px;letter-spacing:.12em;font-weight:bold}.logo small{display:block;font-size:10px;letter-spacing:.35em;font-weight:normal;color:#6b7a6f}
nav a{margin:0 16px;font-size:14px;text-transform:uppercase;letter-spacing:.08em}nav a:hover{color:#b5652b}.icons{font-size:14px}.icons span{margin-left:18px}
.hero{height:78vh;background:url(img/hero.jpg) center/cover;display:flex;align-items:flex-end;padding:60px;color:#fff;position:relative}.hero:before{content:'';position:absolute;inset:0;background:linear-gradient(transparent 40%,rgba(0,0,0,.55))}
.hero div{position:relative;max-width:560px}.hero h1{font-family:Georgia,serif;font-size:54px;margin:0 0 12px}.hero p{font-size:18px}
.btn{display:inline-block;background:#b5652b;color:#fff;padding:14px 30px;text-transform:uppercase;letter-spacing:.1em;font-size:13px;border:0;cursor:pointer}.btn.dark{background:#2f4a3a}
.wrap{max-width:1240px;margin:0 auto;padding:60px 40px}h2{font-family:Georgia,serif;font-size:32px;margin:0 0 24px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:28px}.card img{width:100%;aspect-ratio:4/5;object-fit:cover;background:#eee}.card h3{font-size:15px;margin:12px 0 4px;font-weight:600}.card p{margin:0;color:#5c665f}
.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.tile{height:380px;background-size:cover;background-position:center;display:flex;align-items:flex-end;padding:24px;color:#fff;font-family:Georgia,serif;font-size:28px;text-shadow:0 2px 8px rgba(0,0,0,.6)}
.band{background:#2f4a3a;color:#f3efe6;text-align:center;padding:70px 20px}.band p{max-width:640px;margin:0 auto 24px;font-size:18px;line-height:1.6}
.pdp{display:grid;grid-template-columns:1.2fr 1fr;gap:56px}.pdp img{width:100%;object-fit:cover}.sizes button{border:1px solid #1f2a24;background:none;padding:10px 16px;margin:4px;cursor:pointer}.sizes button.on{background:#1f2a24;color:#fff}
.story img{width:100%;height:460px;object-fit:cover;margin:20px 0}.story p,.policy p,.policy li{font-size:17px;line-height:1.7;max-width:760px}
footer{background:#1f2a24;color:#cfd6cf;padding:56px 40px 30px;font-size:14px}.fcols{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:40px;max-width:1240px;margin:0 auto}footer h4{color:#fff;text-transform:uppercase;letter-spacing:.1em;font-size:12px}footer a{display:block;margin:8px 0}
.sub input{padding:12px;width:65%;border:0}.sub button{padding:12px 16px;background:#b5652b;color:#fff;border:0;cursor:pointer}.social a{display:inline-block;margin-right:14px}
.legal{max-width:1240px;margin:36px auto 0;border-top:1px solid #36443b;padding-top:18px;font-size:12px;color:#8e9a90}
#sms{position:fixed;inset:0;background:rgba(0,0,0,.5);display:none;align-items:center;justify-content:center;z-index:20}#sms .box{background:#faf8f4;display:grid;grid-template-columns:1fr 1fr;max-width:760px;width:92%}#sms .box img{width:100%;height:100%;object-fit:cover}#sms .in{padding:36px;position:relative}#sms h3{font-family:Georgia,serif;font-size:30px;margin:0 0 8px}#sms input{width:100%;padding:12px;margin:8px 0;border:1px solid #bbb}#sms .x{position:absolute;right:14px;top:10px;cursor:pointer;font-size:22px}#sms .fine{font-size:10px;color:#6b7a6f;line-height:1.4}
@media(max-width:800px){.tiles,.pdp,.fcols,#sms .box{grid-template-columns:1fr}nav{display:none}.hero h1{font-size:36px}}"""
open("style.css","w").write(CSS)
HEAD=lambda t:f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{t}</title><meta name="description" content="Cairnwood Outfitters makes durable outdoor apparel and gear in Bend, Oregon. Free shipping over $99."><link rel="stylesheet" href="style.css"><link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>⛰</text></svg>"></head><body>
<div class="ann">Free shipping on orders over $99 &nbsp;|&nbsp; Free returns within 60 days</div>
<header><a class="logo" href="index.html">CAIRNWOOD<small>OUTFITTERS · BEND, OR</small></a><nav><a href="shop.html">Shop</a><a href="shop.html?c=Men">Men</a><a href="shop.html?c=Women">Women</a><a href="shop.html?c=Gear">Gear</a><a href="story.html">Our Story</a></nav><div class="icons"><span>Search</span><span>Account</span><span>Cart (0)</span></div></header>"""
FOOT="""<footer><div class="fcols"><div><h4>Join the Cairnwood Crew</h4><p>Get 10% off your first order, plus early access to new gear and trail reports from Central Oregon.</p><form class="sub" onsubmit="this.innerHTML='<p>Thanks! Check your inbox for your 10% off code.</p>';return false"><input type="email" required placeholder="Email address"><button>Sign up</button></form><p class="social"><a href="https://www.instagram.com/">Instagram</a><a href="https://www.facebook.com/">Facebook</a><a href="https://www.tiktok.com/">TikTok</a><a href="https://www.youtube.com/">YouTube</a></p></div>
<div><h4>Shop</h4><a href="shop.html?c=Men">Men</a><a href="shop.html?c=Women">Women</a><a href="shop.html?c=Gear">Gear</a><a href="shop.html">New Arrivals</a></div>
<div><h4>Help</h4><a href="shipping-returns.html">Shipping &amp; Returns</a><a href="shipping-returns.html#warranty">Lifetime Warranty</a><a href="#" onclick="showSms();return false">Text Alerts</a><a href="mailto:hello@cairnwoodoutfitters.com">Contact Us</a></div>
<div><h4>Company</h4><a href="story.html">Our Story</a><a href="story.html#stewardship">Stewardship</a><a href="story.html">Bend Flagship Store</a></div></div>
<div class="legal">© 2026 Cairnwood Outfitters. 1050 NW Bond St, Bend, OR 97703. All rights reserved. &nbsp; Privacy Policy · Terms of Service · SMS Terms</div></footer>
<div id="sms"><div class="box"><img src="img/trail.jpg" alt="Trail through the forest"><div class="in"><span class="x" onclick="hideSms()">×</span><p style="letter-spacing:.2em;font-size:12px;color:#b5652b">TEXT CLUB</p><h3>Get 15% off when you sign up for texts</h3><p>Be first to know about restocks, trail drops and members-only sales.</p><div id="smsf"><input type="email" placeholder="Email address"><input type="tel" placeholder="Mobile number"><button class="btn" style="width:100%" onclick="document.getElementById('smsf').innerHTML='<p><b>You are in!</b> Reply Y to the text we just sent to confirm and get your 15% off code.</p>';sessionStorage.cw=1">Unlock 15% off</button></div><p class="fine">By signing up, you agree to receive recurring automated marketing texts from Cairnwood Outfitters at the number provided. Consent is not a condition of purchase. Msg and data rates may apply. Msg frequency varies. Reply HELP for help or STOP to cancel.</p><a href="#" onclick="hideSms();return false" style="font-size:12px;text-decoration:underline">No thanks</a></div></div></div>
<script src="products.js"></script><script>
function showSms(){document.getElementById('sms').style.display='flex'}function hideSms(){document.getElementById('sms').style.display='none';sessionStorage.cw=1}
if(!sessionStorage.cw)setTimeout(showSms,4000);
function card(p){return `<a class="card" href="product.html?id=${p.id}"><img src="img/${p.id}.jpg" alt="${p.name}" loading="lazy"><h3>${p.name}</h3><p>$${p.price}</p></a>`}
</script>"""
def page(f,t,body,script=""):open(f,"w").write(HEAD(t)+body+FOOT+f"<script>{script}</script></body></html>")
page("index.html","Cairnwood Outfitters | Outdoor Apparel and Gear from Bend, Oregon",
"""<section class="hero"><div><h1>Built for the Long Way Around</h1><p>Durable layers and trail gear designed in Bend, Oregon and tested in the Cascades.</p><a class="btn" href="shop.html">Shop the Fall Collection</a></div></section>
<div class="wrap"><h2>New This Season</h2><div class="grid" id="g"></div></div>
<div class="wrap" style="padding-top:0"><div class="tiles"><a class="tile" href="shop.html?c=Men" style="background-image:url(img/men.jpg)">Shop Men</a><a class="tile" href="shop.html?c=Women" style="background-image:url(img/women.jpg)">Shop Women</a><a class="tile" href="shop.html?c=Gear" style="background-image:url(img/three-sisters-tent.jpg)">Shop Gear</a></div></div>
<section class="band"><h2>Made to Last a Lifetime</h2><p>Every Cairnwood product is backed by our lifetime warranty. If it fails, we repair it or replace it. That is a promise we have kept since 2011.</p><a class="btn" href="story.html">Read Our Story</a></section>""",
"document.getElementById('g').innerHTML=PRODUCTS.slice(0,8).map(card).join('')")
page("shop.html","Shop All | Cairnwood Outfitters",
"""<div class="wrap"><h2 id="t">Shop All</h2><p id="n" style="color:#5c665f;margin-top:-12px"></p><div class="grid" id="g"></div></div>""",
"const c=new URLSearchParams(location.search).get('c');const l=c?PRODUCTS.filter(p=>p.cat==c):PRODUCTS;if(c){document.getElementById('t').textContent=\"Shop \"+c;document.title='Shop '+c+' | Cairnwood Outfitters'}document.getElementById('n').textContent=l.length+' products';document.getElementById('g').innerHTML=l.map(card).join('')")
page("product.html","Cairnwood Outfitters",
"""<div class="wrap"><div class="pdp" id="p"></div></div><div class="wrap" style="padding-top:0"><h2>You May Also Like</h2><div class="grid" id="g"></div></div>""",
"""const id=new URLSearchParams(location.search).get('id')||PRODUCTS[0].id;const p=PRODUCTS.find(x=>x.id==id)||PRODUCTS[0];document.title=p.name+' | Cairnwood Outfitters';
document.getElementById('p').innerHTML=`<img src="img/${p.id}.jpg" alt="${p.name}"><div><p style="color:#6b7a6f;text-transform:uppercase;font-size:12px;letter-spacing:.1em">${p.cat}</p><h1 style="font-family:Georgia,serif;margin:0 0 8px">${p.name}</h1><p style="font-size:22px">$${p.price}</p><p>★★★★★ <span style="color:#5c665f">${(p.price*7)%180+40} reviews</span></p><p style="line-height:1.7">${p.desc}</p><p><b>Size</b></p><div class="sizes">${p.sizes.map((s,i)=>`<button class="${i==1||p.sizes.length==1?'on':''}" onclick="[...this.parentNode.children].forEach(b=>b.className='');this.className='on'">${s}</button>`).join('')}</div><p><button class="btn" style="width:100%;margin-top:16px" onclick="this.textContent='Added to cart'">Add to Cart</button></p><p style="font-size:14px;color:#5c665f">Free shipping over $99 · Free 60 day returns · Lifetime warranty</p><p style="font-size:14px">Pay in 4 interest-free installments at checkout.</p></div>`;
document.getElementById('g').innerHTML=PRODUCTS.filter(x=>x.id!=p.id).slice(0,4).map(card).join('')""")
page("story.html","Our Story | Cairnwood Outfitters","""<div class="wrap story"><h2>Our Story</h2><p>Cairnwood started in 2011 in a one-car garage in Bend, Oregon, with a sewing machine, a stack of waxed canvas and a simple idea: outdoor gear should last long enough to collect stories.</p><img src="img/story-river.jpg" alt="River canyon in Central Oregon"><p>Today we are a team of designers, guides and gear nerds who still test every product on the trails around the Three Sisters, Smith Rock and the Deschutes River. Our flagship store sits on Bond Street downtown, and we ship to adventurers in all 50 states and Canada.</p><h2 id="stewardship" style="margin-top:40px">Stewardship</h2><img src="img/story-flannel.jpg" alt="Hiker in a flannel shirt in the forest"><p>We give 1% of every sale to local trail and watershed organizations, use recycled or organic fabrics in over 70% of our line and run a repair program that has kept more than 40,000 garments in use. Wear it out, send it back, and we will fix it.</p><img src="img/campfire.jpg" alt="Campfire"><p>Thanks for being part of the Cairnwood Crew. We will see you out there.</p></div>""")
page("shipping-returns.html","Shipping and Returns | Cairnwood Outfitters","""<div class="wrap policy"><h2>Shipping &amp; Returns</h2><h3>Shipping</h3><ul><li>Free standard shipping on US orders over $99 (3 to 6 business days).</li><li>Standard shipping under $99: $7.95.</li><li>Expedited (2 business days): $18. Overnight: $32.</li><li>Orders placed before 1 PM PT ship the same business day from our Bend, OR warehouse.</li><li>We ship to Canada. Duties and taxes are calculated at checkout.</li></ul><h3>Returns &amp; Exchanges</h3><p>Not the right fit? Return unworn items within 60 days for a full refund or free exchange. Start a return from your account or with your order number and email. Return shipping is free for US orders.</p><h3 id="warranty">Lifetime Warranty</h3><p>If a Cairnwood product fails due to a defect in materials or workmanship, we will repair it, replace it or refund it for the life of the product. Normal wear and tear can be repaired for a small fee through our repair program.</p><h3>Questions?</h3><p>Email hello@cairnwoodoutfitters.com or text HELP to our customer care line. We answer Monday through Saturday, 8 AM to 6 PM PT.</p></div>""")
